280	fn qr_texture(ctx: &Context, payload: &str) -> Option<egui::TextureHandle> {
281	    let code = qrcode::QrCode::new(payload.as_bytes()).ok()?;
282	    let width = code.width();
283	    let modules = code.to_colors();
284	    let side = (width + 2 * QR_QUIET) * QR_SCALE;
285	    let mut pixels = vec![egui::Color32::WHITE; side * side];
286	    for (i, module) in modules.iter().enumerate() {
287	        if *module != qrcode::Color::Dark {
288	            continue;
289	        }
290	        let (x, y) = (i % width + QR_QUIET, i / width + QR_QUIET);
291	        for dy in 0..QR_SCALE {
292	            for dx in 0..QR_SCALE {
293	                pixels[(y * QR_SCALE + dy) * side + x * QR_SCALE + dx] = egui::Color32::BLACK;
294	            }
295	        }
296	    }
297	    let image = egui::ColorImage::new([side, side], pixels);
298	    Some(ctx.load_texture("remote-pairing-qr", image, egui::TextureOptions::NEAREST))
299	}
300	
301	/// The first sixteen hex digits of a key hash in groups of four: what
302	/// a person compares against the client's screen.
303	fn short_hash(hex: &str) -> String {
304	    hex.chars()
305	        .take(16)
306	        .collect::<Vec<_>>()
307	        .chunks(4)
308	        .map(|c| c.iter().collect::<String>())
309	        .collect::<Vec<_>>()
310	        .join(" ")
311	}
312	
313	/// "ABCD EFGH": the code in two halves, as it is read aloud.
314	fn spaced(code: &str) -> String {
315	    let (a, b) = code.split_at(code.len() / 2);
316	    format!("{a} {b}")
317	}

